contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable {
        require(amount == 0);
        uint before = address(c).balance;
        bool reverted;
        c.withdraw(amount); if (__ESBMC_reverted()) return;
        reverted = false;
        assert(!reverted && address(c).balance == before);
    }
    receive() external payable {}
}

